private func loadSound(_ name: String) -> AVAudioPlayer? {
    // Try common audio formats
    let extensions = ["mp3", "wav", "m4a", "aac", "caf"]

    for ext in extensions {
        if let url = Bundle.main.url(forResource: name, withExtension: ext) {
