/// Normalizes an angle to the range [-π, π]
public static func normalize(_ angle: CGFloat) -> CGFloat {
    var result = angle.truncatingRemainder(dividingBy: 2 * .pi)
    if result > .pi {
        result -= 2 * .pi
    } else if result < -.pi {
        result += 2 * .pi
    }
    return result
}

